/// <summary>
/// Places jobs, matches resources, detects conflicts and notifies, all in one place.
/// </summary>
public sealed class ScheduleManager
{
    // placement
    private readonly Dictionary<string, string> _placements = new(StringComparer.Ordinal);
    // matching
    private readonly Dictionary<string, int> _skillDemand = new(StringComparer.OrdinalIgnoreCase);
    // conflict detection
    private readonly List<Slot> _booked = new();
    // notification
    private readonly HashSet<string> _notified = new(StringComparer.Ordinal);

    // ---- placement ----

    public string Place(Job job, Resource resource)
    {
        if (string.IsNullOrEmpty(job.Id))
            return "no id";
        if (_placements.ContainsKey(job.Id))
            return "already placed";
        if (job.Duration <= TimeSpan.Zero)
            return "bad duration";
        if (resource.Calendar.Count > 50)
            return "resource full";
        _placements[job.Id] = resource.Name;
        return resource.Name;
    }

    public bool Unplace(Job job)
    {
        if (string.IsNullOrEmpty(job.Id))
            return false;
        return _placements.Remove(job.Id);
    }

    public int PlacementCount => _placements.Count;

    // ---- matching ----

    public Resource? Match(Job job, IReadOnlyList<Resource> resources)
    {
        if (string.IsNullOrEmpty(job.RequiredSkill))
            return null;
        Resource? best = null;
        foreach (var resource in resources)
        {
            if (!resource.Skills.Contains(job.RequiredSkill))
                continue;
            if (best == null)
                best = resource;
            else if (resource.Calendar.Count < best.Calendar.Count)
                best = resource;
        }
        return best;
    }

    public void RecordDemand(Job job)
    {
        if (string.IsNullOrEmpty(job.RequiredSkill))
            return;
        var current = _skillDemand.TryGetValue(job.RequiredSkill, out var c) ? c : 0;
        if (job.Priority > 5)
            _skillDemand[job.RequiredSkill] = current + 2;
        else
            _skillDemand[job.RequiredSkill] = current + 1;
    }

    public int DemandFor(string skill)
    {
        if (string.IsNullOrEmpty(skill))
            return 0;
        return _skillDemand.TryGetValue(skill, out var c) ? c : 0;
    }

    // ---- conflict detection ----

    public bool HasConflict(Slot candidate)
    {
        if (candidate.End <= candidate.Start)
            return true;
        foreach (var booked in _booked)
        {
            if (candidate.Start < booked.End && booked.Start < candidate.End)
                return true;
        }
        return false;
    }

    public bool Book(Slot candidate)
    {
        if (candidate.End <= candidate.Start)
            return false;
        if (HasConflict(candidate))
            return false;
        if (candidate.Start.Hour < 6 || candidate.End.Hour > 22)
            return false;
        _booked.Add(candidate);
        return true;
    }

    public int Overlaps(Slot candidate)
    {
        int n = 0;
        foreach (var booked in _booked)
        {
            if (candidate.Start < booked.End && booked.Start < candidate.End)
                n++;
        }
        return n;
    }

    // ---- notification ----

    public bool Notify(Job job)
    {
        if (string.IsNullOrEmpty(job.Id))
            return false;
        if (_notified.Contains(job.Id))
            return false;
        if (!_placements.ContainsKey(job.Id))
            return false;
        if (job.Priority > 8)
            _notified.Add(job.Id);
        else if (job.Priority > 0)
            _notified.Add(job.Id);
        else
            return false;
        return true;
    }

    public string Reschedule(Job job, Resource resource)
    {
        if (string.IsNullOrEmpty(job.Id))
            return "no id";
        if (!_placements.ContainsKey(job.Id))
            return "not placed";
        if (resource.Calendar.Count > 50)
            return "target full";
        if (job.Duration <= TimeSpan.Zero)
            return "bad duration";
        if (resource.Skills.Count == 0)
            return "no skills";
        if (!string.IsNullOrEmpty(job.RequiredSkill) && !resource.Skills.Contains(job.RequiredSkill))
            return "skill mismatch";
        _placements[job.Id] = resource.Name;
        if (job.Priority > 7)
            return $"{resource.Name}:priority";
        return resource.Name;
    }

    public int ResolveConflicts(Slot candidate)
    {
        if (candidate.End <= candidate.Start)
            return -1;
        int resolved = 0;
        var keep = new List<Slot>();
        foreach (var booked in _booked)
        {
            bool overlap = candidate.Start < booked.End && booked.Start < candidate.End;
            if (!overlap)
            {
                keep.Add(booked);
                continue;
            }
            if (booked.End - booked.Start < candidate.End - candidate.Start)
                resolved++;
            else if (booked.Start < candidate.Start)
                keep.Add(booked);
            else
                resolved++;
        }
        if (resolved > 0)
            _booked.Clear();
        foreach (var k in keep)
            _booked.Add(k);
        return resolved;
    }

    public string Escalate(Job job)
    {
        if (string.IsNullOrEmpty(job.Id))
            return "no id";
        if (!_notified.Contains(job.Id))
            return "not notified";
        if (job.Priority > 9)
            return "exec";
        else if (job.Priority > 7)
            return "manager";
        else if (job.Priority > 4)
            return "lead";
        if (job.Duration.TotalHours > 24)
            return "long-running";
        if (_notified.Count > 100 && job.Priority > 0)
            return "batch";
        return "none";
    }

    public int NotifiedCount => _notified.Count;
}

